class Solution {
    public int deleteString(String s){
        int n=s.length();
        int[][] lcp=new int[n+1][n+1];
        for(int i=n-1;i>=0;i--)for(int j=n-1;j>i;j--)if(s.charAt(i)==s.charAt(j))lcp[i][j]=lcp[i+1][j+1]+1;
        int[] dp=new int[n];
        for(int i=n-1;i>=0;i--){
            dp[i]=1;
            for(int length=1;i+2*length<=n;length++)if(lcp[i][i+length]>=length)dp[i]=Math.max(dp[i],1+dp[i+length]);
        }
        return dp[0];
    }
}

